// ─── File: ExhaustiveDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.exhaustive;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class ExhaustiveDemo {
    private static final Logger log = Logger.getLogger(ExhaustiveDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ResultDispatcher dispatcher = new ResultDispatcher();
        List<TransactionResult> results = List.of(
            new Approved("TXF-1", new BigDecimal("50000")),
            new Approved("TXF-2", new BigDecimal("1500000")),   // high-value → guarded case
            new Declined("TXF-3", "Insufficient funds"),
            new Pending("TXF-4", "Awaiting OTP"));

        for (TransactionResult r : results) {
            log.info(() -> dispatcher.dispatch(r));
        }
    }
}

// ─── Sealed result type; permits inferred from same file ───
sealed interface TransactionResult { String reference(); }
record Approved(String reference, BigDecimal amount) implements TransactionResult { }
record Declined(String reference, String reason)     implements TransactionResult { }
record Pending(String reference, String note)        implements TransactionResult { }

// ─── Would be in service/ResultDispatcher.java ───
class ResultDispatcher {
    private static final BigDecimal HIGH_VALUE = new BigDecimal("1000000");

    // EXHAUSTIVE switch over a SEALED type. No `default` — the compiler proves
    // every permitted subtype is handled. Record patterns extract fields safely.
    String dispatch(TransactionResult r) {
        return switch (r) {
            // Guarded pattern: high-value approvals need extra compliance review.
            case Approved a when a.amount().compareTo(HIGH_VALUE) >= 0 ->
                "APPROVED-HIGHVALUE " + a.reference() + " Rs." + a.amount() + " (compliance review)";
            case Approved(String ref, BigDecimal amt) ->
                "APPROVED " + ref + " Rs." + amt;
            case Declined(String ref, String reason) ->
                "DECLINED " + ref + " reason=" + reason;
            case Pending(String ref, String note) ->
                "PENDING  " + ref + " note=" + note;
            // NOTE: if a new permitted subtype were added to TransactionResult
            // and NOT handled here, THIS switch would FAIL TO COMPILE.
            // Adding a `default` would hide that safety — so we omit it deliberately.
        };
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
